package alpha

import "testing"

func TestPass(t *testing.T) {
	if Add(1, 2) != 3 {
		t.Fatalf("unexpected sum")
	}
}

func TestFail(t *testing.T) {
	got := Add(1, 1)
	t.Log("failing on purpose")
	if got != 3 {
		t.Fatalf("expected 3, got %d", got)
	}
}

func TestSkip(t *testing.T) {
	t.Skip("skipping on purpose")
}

func TestSubtests(t *testing.T) {
	t.Run("PassChild", func(t *testing.T) {
		if Add(2, 2) != 4 {
			t.Fatalf("unexpected child sum")
		}
	})
	t.Run("FailChild", func(t *testing.T) {
		t.Log("child failure")
		if Add(2, 2) != 5 {
			t.Fatalf("expected 5, got %d", Add(2, 2))
		}
	})
}

package alpha

func Add(a, b int) int {
	return a + b
}

